    endpoints = []
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 1:
                tracks.append([(r, c + k) for k in (1, 2) if 0 <= c + k < w])
                endpoints.append((r - 1, c + 2, 1))
            elif color == 2:
                tracks.append([(r, c - k) for k in (1, 2, 3) if 0 <= c - k < w])
                endpoints.append((r, c - 4, 2))
            elif color == 3:
                tracks.append([(r + k, c) for k in (1, 2) if 0 <= r + k < h])
                endpoints.append((r + 3, c, 3))
            elif color == 6:
                tracks.append([(r - k, c) for k in (1, 2, 3, 4, 5) if 0 <= r - k < h])
                endpoints.append((r - 6, c, 6))
    counts = {}
    for track in tracks:
        for point in track:
            counts[point] = counts.get(point, 0) + 1
    crossings = [point for point, count in counts.items() if count > 1]
    for track in tracks:
        for r, c in track:
            if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
                out[r][c] = 5
    for r, c, color in endpoints:
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = color
    for r, c in crossings:
